import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Paper–Implementation Alignment Plan — design detail","description":"","frontmatter":{"title":"Paper–Implementation Alignment Plan — design detail","type":"design","date":"2026-09-18T00:00:00.000Z","updated":"2026-10-29T00:00:00.000Z","refs":["ADR-0120"]},"headers":[],"relativePath":"handl/project/design/0120-paper-implementation-alignment.md","filePath":"vendored/handl/project/design/0120-paper-implementation-alignment.md"}`),a={name:`handl/project/design/0120-paper-implementation-alignment.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0120-paper–implementation-alignment-plan-—-design-detail" tabindex="-1">ADR-0120: Paper–Implementation Alignment Plan — design detail <a class="header-anchor" href="#adr-0120-paper–implementation-alignment-plan-—-design-detail" aria-label="Permalink to “ADR-0120: Paper–Implementation Alignment Plan — design detail”">​</a></h1><p>Moved verbatim from ADR-0120 (ADR-0161 size budget). The ADR carries the rules; this page carries the mechanism, tables and rationale.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Execute the alignment in five phases; ordering is load-bearing: <code>1 → 2 → 3 → (4, 5 in parallel)</code>.</p><h3 id="phase-1-—-arrows-as-values" tabindex="-1">Phase 1 — Arrows as values <a class="header-anchor" href="#phase-1-—-arrows-as-values" aria-label="Permalink to “Phase 1 — Arrows as values”">​</a></h3><ol><li>A <code>function</code> used as a <em>value</em> lowers to <code>Arr { value: &lt;Term&gt; }</code> (quote). No environment is captured — it was already resolved at lower time.</li><li><code>call(f, x)</code> lowers to <code>seq(pair(quote f, x), app)</code> for env-bound <code>f</code>; <code>seq(x, f)</code> remains the encoding of flow <code>x &gt;&gt;&gt; f</code>.</li><li><code>desugar.data</code>&#39;s recursor is re-encoded as <code>loop(step)</code> feedback instead of <code>inner(inner)</code> self-application (the lambda-calculus encoding).</li><li>No currying. Parameters are products; if partial application is ever proven necessary it is expressed as prefix-splice <code>seq(fanout(const a, id), f)</code> — pure products, no closures.</li></ol><h3 id="phase-2-—-composition-axes" tabindex="-1">Phase 2 — Composition axes <a class="header-anchor" href="#phase-2-—-composition-axes" aria-label="Permalink to “Phase 2 — Composition axes”">​</a></h3><ol start="5"><li><code>Term::Seq</code> gains an <code>axis</code> slot (default <code>0</code>); <code>f &gt;&gt;&gt; g</code> is <code>&gt;&gt;&gt;[0]</code>.</li><li><code>&gt;&gt;&gt;[k]</code> surface syntax is a YAML/grammar change only.</li><li>Types track globular source/target at every level <code>≤ n</code>; the typing rule for <code>a &gt;&gt;&gt;[k] b</code> is <code>tgt_k(a) = src_k(b)</code>.</li></ol><h3 id="phase-3-—-dim-unification" tabindex="-1">Phase 3 — <code>dim</code> unification <a class="header-anchor" href="#phase-3-—-dim-unification" aria-label="Permalink to “Phase 3 — dim unification”">​</a></h3><ol start="8"><li>Merge <code>ArrSource::Foreign(grade)</code> into morphism dimension; the <code>~[n]~&gt;</code> bracket means dimension. Open sub-question: grades are names and dims are numbers, so handler lookup becomes dimension-typed.</li><li>Effects are re-read as cells: <code>op</code> is a cell, <code>handle</code> a cell interpreter (<code>(N+1)</code>-cell mapping an effectful <code>N</code>-cell to a pure one, per ADR-0119 §6).</li></ol><h3 id="phase-4-—-dependent-structure" tabindex="-1">Phase 4 — Dependent structure <a class="header-anchor" href="#phase-4-—-dependent-structure" aria-label="Permalink to “Phase 4 — Dependent structure”">​</a></h3><ol start="10"><li><code>Family&lt;A&gt;</code>, <code>Π</code>, <code>Σ</code> enter via <code>types.yaml</code> + <code>desugar</code> — extending the existing <code>data</code>/indexed-family/recursor machinery.</li><li>Reindexing <code>f*</code> is composition (<code>· &gt;&gt;&gt; f</code>); <code>Σ_f ⊣ f* ⊣ Π_f</code> is expressed as laws (<code>~[2]~&gt;</code> cells), not engine primitives.</li></ol><h3 id="phase-5-—-laws-as-m-2-terms" tabindex="-1">Phase 5 — Laws as <code>M[2]</code> terms <a class="header-anchor" href="#phase-5-—-laws-as-m-2-terms" aria-label="Permalink to “Phase 5 — Laws as M[2] terms”">​</a></h3><ol start="12"><li><code>f ~[2]~&gt; g</code> parses to a <code>Term</code> and feeds <code>law_inference</code> — no separate laws fragment.</li><li><code>Path</code>/<code>Equiv</code>/<code>Refine</code>/<code>witness</code>/<code>cell_*</code>/<code>whisker_*</code> are <strong>derived arrows</strong> (interchange + <code>compose</code>), not engine primitives; the <code>option_b</code> op surface collapses into the generic combinators.</li></ol><h3 id="decision-gates" tabindex="-1">Decision gates <a class="header-anchor" href="#decision-gates" aria-label="Permalink to “Decision gates”">​</a></h3><ul><li><strong>Strict vs weak:</strong> resolved — weak (proof-relevant). <code>law_inference</code> stays as the strict fast-path.</li><li><strong>Globular vs cubical:</strong> resolved — globular. Reopen only if univalence- computing equality becomes a requirement; then as a cube-diagram fragment, not a rewrite.</li></ul><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p><code>research/PAPER.md</code> describes the target architecture: <code>M[n]&lt;A,B&gt;</code> dimension-polymorphic morphisms, laws as higher morphisms, <code>&gt;&gt;&gt;[k]</code> axis-parameterized composition, <code>Family</code>/<code>Π</code>/<code>Σ</code>, and effects as higher cells. The <code>Term</code> kernel (<code>plugin-engine/src/term.rs</code>: <code>Arr</code>, <code>Const</code>, <code>Op</code>, <code>Seq</code>, <code>First</code>, <code>Choice</code>, <code>Loop</code>, <code>App</code>, <code>Handle</code>; <code>dim: Box&lt;Term&gt;</code> on <code>Arr</code>/<code>Op</code>) embodies the shape but has gaps that surfaced as concrete failures:</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>Fixes unblocked by Phase 1:</strong> <code>module_returns_closure</code>,</li><li><strong>Ops removed, not added:</strong> <code>cell_comp_*</code>, <code>whisker_*</code>, <code>cell_id</code>,</li><li><strong><code>eval_rec</code>/<code>rec</code> region:</strong> superseded by <code>loop</code>-encoded recursion where</li><li><strong>Deferred:</strong> cubical Kan (<code>transport</code>/<code>Equiv</code> computing), strictness</li><li><strong>Known debt:</strong> <code>lower_ast</code>&#39;s <code>match node.kind</code> table (ADR-0105) remains</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0120-paper-implementation-alignment.html"><code>design/0120-paper-implementation-alignment.md</code></a>.</p>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};